/**
 * Why pointsAwarded is 0: "repeat_today" when this spotter already earned points for this cat today (Athens day). Null otherwise.
 */
export type ResolveResultPointsReason = typeof ResolveResultPointsReason[keyof typeof ResolveResultPointsReason] | null;


export const ResolveResultPointsReason = {
  repeat_today: 'repeat_today',
} as const;

export type BadgeProgressGroup = typeof BadgeProgressGroup[keyof typeof BadgeProgressGroup];


export const BadgeProgressGroup = {
  first_steps: 'first_steps',
  coming_back: 'coming_back',
  weekly: 'weekly',
  finding: 'finding',
  covering: 'covering',
} as const;

export interface BadgeProgress {
  id: string;
  group: BadgeProgressGroup;
  earned: boolean;
  /** Progress towards the goal; null for badges earned at a moment (Pathfinder, Trailblazer). */
  value: number | null;
  goal: number | null;
}

export interface Profile {
  deviceId: string;
  spotterCode: string;
  username?: string | null;
  nickname?: string | null;
  points: number;
  totalSightings: number;
  uniqueCatsDiscovered: number;
  catsSpotted: number;
  /** Every badge this spotter has earned. Badges are never taken away. */
  badges: string[];
  /** Every badge in the catalogue, in display order, with progress. */
  badgeProgress: BadgeProgress[];
  /** Earned badges not yet seen on the Badges tab ("New"). */
  newBadgeIds: string[];
  /** Points earned this week (Monday to Monday, Europe/Athens). */
  weekPoints: number;
  /** Ids of cats this device owns. Only returned on the device's own profile route (the deviceId path param is the credential); never exposed in public payloads. */
  ownedCatIds: number[];
  /** Consecutive days (Europe/Athens) with at least one resolved sighting. Survives a day not yet spotted; breaks after a full missed day. */
  currentStreakDays: number;
  /** Ids of cats this device has personally spotted, driving the collected-vs-locked treatment on the cat grids. Same privacy reasoning as ownedCatIds. */
  spottedCatIds: number[];
  /** Size of the whole cat-alog — the denominator in "12 of 142". */
  totalCats: number;
}

export interface ResolveResult {
  cat: Cat;
  pointsAwarded: number;
  /** Why pointsAwarded is 0: "repeat_today" when this spotter already earned points for this cat today (Athens day). Null otherwise. */
  pointsReason: ResolveResultPointsReason;
  isNewCat: boolean;
  /** Badges this spot earned, each reported by exactly one spot. */
  newBadges: string[];
  /** The celebration moment queued for newBadges, or null when this spot earned no badge. */
  momentId: number | null;
  profile: Profile;
  /** Whether to ask this spotter the ear-tip question about this cat. False once this device has given any ear-tip answer for this cat ("clipped", "looks whole" or "can't tell"), so each spotter is asked once per cat (data spine plan, decision Q3 → B). */
  askEarTip: boolean;
}

/**
 * Is the ear tip clipped? "clipped_unsure" means clipped, but the spotter isn't sure which ear. Omit to skip.
 */
export type SightingAnswersRequestEarTip = typeof SightingAnswersRequestEarTip[keyof typeof SightingAnswersRequestEarTip];


export const SightingAnswersRequestEarTip = {
  clipped_left: 'clipped_left',
  clipped_right: 'clipped_right',
  clipped_unsure: 'clipped_unsure',
  looks_whole: 'looks_whole',
  cant_tell: 'cant_tell',
} as const;

/**
 * Do they have food and water? Omit to skip.
 */
export type SightingAnswersRequestFoodAndWater = typeof SightingAnswersRequestFoodAndWater[keyof typeof SightingAnswersRequestFoodAndWater];


export const SightingAnswersRequestFoodAndWater = {
  yes: 'yes',
  no: 'no',
  cant_tell: 'cant_tell',
} as const;

export interface SightingAnswersRequest {
  /** Device credential of the sighting owner; must match the sighting */
  deviceId: string;
  /** Is the ear tip clipped? "clipped_unsure" means clipped, but the spotter isn't sure which ear. Omit to skip. */
  earTip?: SightingAnswersRequestEarTip;
  /** Do they have food and water? Omit to skip. */
  foodAndWater?: SightingAnswersRequestFoodAndWater;
  /**
     * "Anything you noticed?" Seen only by the Syros Cats team, never published. Blank is treated as skipped.
     * @maxLength 500
     */
  note?: string;
  /** With earTip: replace this device's own current ear-tip answer for this cat (from the cat's page). The old answer is kept, marked replaced. Refused with EAR_TIP_CHECKED once Syros Cats have checked it. Without this, a second ear-tip answer is left out. */
  changeEarTip?: boolean;
}

export type MyOpenSightingsEarTipState = typeof MyOpenSightingsEarTipState[keyof typeof MyOpenSightingsEarTipState];


export const MyOpenSightingsEarTipState = {
  open: 'open',
  answered: 'answered',
  checked: 'checked',
} as const;

export type MyOpenSightingsEarTipCurrent = typeof MyOpenSightingsEarTipCurrent[keyof typeof MyOpenSightingsEarTipCurrent];


export const MyOpenSightingsEarTipCurrent = {
  clipped_left: 'clipped_left',
  clipped_right: 'clipped_right',
  clipped_unsure: 'clipped_unsure',
  looks_whole: 'looks_whole',
  cant_tell: 'cant_tell',
} as const;

/**
 * This device's ear-tip answer for this cat. "open": not answered yet. "answered": `current` is the answer, and it can be changed. "checked": Syros Cats have checked it; it can't be changed.
 */
export type MyOpenSightingsEarTip = {
  state: MyOpenSightingsEarTipState;
  current?: MyOpenSightingsEarTipCurrent;
};

export type OpenSightingOpen = {
  foodAndWater: boolean;
  note: boolean;
};

export interface OpenSighting {
  sightingId: number;
  takenAt: string;
  photoUrl: string | null;
  open: OpenSightingOpen;
}

export interface MyOpenSightings {
  /** This device's ear-tip answer for this cat. "open": not answered yet. "answered": `current` is the answer, and it can be changed. "checked": Syros Cats have checked it; it can't be changed. */
  earTip: MyOpenSightingsEarTip;
  sightings: OpenSighting[];
}

export type SightingAnswersResultRecordedItem = typeof SightingAnswersResultRecordedItem[keyof typeof SightingAnswersResultRecordedItem];


export const SightingAnswersResultRecordedItem = {
  ear_tip: 'ear_tip',
  food_and_water: 'food_and_water',
  note: 'note',
} as const;

export interface SightingAnswersResult {
  /** Which answers were written (empty if everything was skipped) */
  recorded: SightingAnswersResultRecordedItem[];
}

export interface UpdateProfileRequest {
  /**
     * Display name for the leaderboard; empty or null clears it
     * @maxLength 24
     */
  nickname?: string | null;
}

export interface UsernameAvailability {
  available: boolean;
  /** Why the name is unavailable ("taken", "invalid" or "offensive") */
  reason?: string | null;
}

export interface UsernameSuggestions {
  suggestions: string[];
}

export interface ClaimUsernameRequest {
  /**
     * @minLength 3
     * @maxLength 24
     */
  username: string;
}

export interface ClaimedUsername {
  /** @nullable */
  username: string | null;
}

export type BadgeMomentKind = typeof BadgeMomentKind[keyof typeof BadgeMomentKind];


export const BadgeMomentKind = {
  badges: 'badges',
  week_result: 'week_result',
  history: 'history',
} as const;

export interface BadgeMoment {
  id: number;
  kind: BadgeMomentKind;
  badgeIds: string[];
  weekStart: string | null;
  place: number | null;
  weekPoints: number | null;
}

export interface BadgeMoments {
  moments: BadgeMoment[];
}

export interface LastWeekEntry {
  place: number;
  /** The frozen display name, or null for "a spotter" */
  name: string | null;
  points: number;
}

export interface LeaderboardEntry {
  /** Opaque public spotter identifier (never the raw device id) */
  spotterCode: string;
  username?: string | null;
  nickname?: string | null;
  points: number;
  uniqueCatsDiscovered: number;
  rank: number;
}

export interface WeekBoard {
  /** The Athens Monday this week began, as YYYY-MM-DD */
  weekStart: string;
  /** When this week closes (next Monday 00:00 Athens) */
  endsAt: string;
  entries: LeaderboardEntry[];
  /** Last week's frozen result; empty until that week has closed */
  lastWeek: LastWeekEntry[];
}

/**
 * The device id, for the one route that takes it in a header rather than the path (DELETE /me), so it never appears in a request log.
 */
export type DeviceIdHeaderParameter = string;

/**
 * Device-generated private secret proving ownership of the device id. Bound to the device id on first use; must match on later requests.
 */
export type DeviceSecretHeaderParameter = string;

export type ListCatsParams = {
lat?: number;
lng?: number;
/**
 * 1-based page number. Defaults to 1.
 * @minimum 1
 */
page?: number;
/**
 * Cats per page. Defaults to 100; at most 200.
 * @minimum 1
 * @maximum 200
 */
pageSize?: number;
};

export type CheckUsernameAvailabilityParams = {
name: string;
};

export type MarkAllNotificationsRead200 = {
  updated: number;
};

export type MarkNotificationRead200 = {
  updated: number;
};

export type RegisterPushToken200 = {
  ok: boolean;
};

